/// The app-facing API for `ReservedFieldProbe` — one model, like the JS client.
/// Reads span every open document by default (scope to specific docs with
/// `options: QueryOptions(documents: [docId])`); `save(in:)` / `delete(in:)`
/// target one document and throw if it isn't open. Backed by the configured
/// default `JsBaoClient` (see `JsBaoClient.configureDefault`).
internal extension ReservedFieldProbe {
    // MARK: Reads (cross-document by default)

    /// Query across all open documents. Rows that fail to decode (schema
    /// drift) are skipped — but never silently: each one is logged with
    /// the row id and the unreadable field(s) and reported to
    /// `PrimitiveRowDecoder.onDecodeFailure`. Scope to one/some docs via
    /// `options.documents`.
    static func query(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil) throws -> [ReservedFieldProbe] {
        let rows = try JsBaoClient.requireDefault()
            .codegen.query(primitiveSchema, filter: filter, options: options)
        return PrimitiveRowDecoder.decodeAll(rows, as: ReservedFieldProbe.self)
    }

    /// Query across all open documents and batch-prefetch related
    /// records into each row's `related` bag. Mirrors JS
    /// `BaseModel.query(filter, { include })`.
    static func query(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil, include: [Include]) throws -> [ReservedFieldProbe] {
        let rows = try JsBaoClient.requireDefault()
            .codegen.query(primitiveSchema, filter: filter, options: options, include: include)
        return PrimitiveRowDecoder.decodeAll(rows, as: ReservedFieldProbe.self)
    }

    /// Paginated query across all open documents. Returns the page's
    /// rows plus `nextCursor`/`prevCursor`/`hasMore` — round-trip
    /// `nextCursor` via `options.cursor` to page. Mirrors JS
    /// `BaseModel.query()`'s `{ data, nextCursor, hasMore }` shape.
    static func queryPaged(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil) throws -> PagedQueryResult<ReservedFieldProbe> {
        let page = try JsBaoClient.requireDefault()
            .codegen.queryPaged(primitiveSchema, filter: filter, options: options)
        return PagedQueryResult(
            data: PrimitiveRowDecoder.decodeAll(page.data, as: ReservedFieldProbe.self),
            nextCursor: page.nextCursor,
            prevCursor: page.prevCursor,
            hasMore: page.hasMore
        )
    }

    /// Paginated query with query-time relationship includes.
    static func queryPaged(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil, include: [Include]) throws -> PagedQueryResult<ReservedFieldProbe> {
        let page = try JsBaoClient.requireDefault()
            .codegen.queryPaged(primitiveSchema, filter: filter, options: options, include: include)
        return PagedQueryResult(
            data: PrimitiveRowDecoder.decodeAll(page.data, as: ReservedFieldProbe.self),
            nextCursor: page.nextCursor,
            prevCursor: page.prevCursor,
            hasMore: page.hasMore
        )
    }

    /// Count across all open documents.
    static func count(_ filter: DocumentFilter? = nil) throws -> Int {
        try JsBaoClient.requireDefault().codegen.count(primitiveSchema, filter: filter)
    }

    /// Every record across all open documents. Synchronous like the
    /// rest of the facade reads (#1156) — the shared store never
    /// suspends. Throws `PrimitiveDecodeError` if any stored row no
    /// longer decodes as `ReservedFieldProbe` — JS `findAll` never drops rows,
    /// so schema drift surfaces loudly instead of silently shrinking
    /// the result.
    static func findAll() throws -> [ReservedFieldProbe] {
        try JsBaoClient.requireDefault()
            .codegen.query(primitiveSchema, filter: nil, options: nil)
            .map { row in
                guard let decoded = ReservedFieldProbe(row: row) else {
                    throw PrimitiveDecodeError(modelName: modelName, row: row, schema: primitiveSchema)
                }
                return decoded
            }
    }

    /// First record with `id` across all open documents; `nil` only when
    /// no open document has it. Synchronous like the rest of the facade
    /// reads (#1156) — the shared store never suspends. Throws
    /// `PrimitiveDecodeError` when the row exists but no longer decodes
    /// as `ReservedFieldProbe` — distinct from the `nil` not-found case.
    static func find(_ id: String) throws -> ReservedFieldProbe? {
        guard let row = JsBaoClient.requireDefault().codegen.find(primitiveSchema, id: id) else {
            return nil
        }
        guard let decoded = ReservedFieldProbe(row: row) else {
            throw PrimitiveDecodeError(modelName: modelName, row: row, schema: primitiveSchema)
        }
        return decoded
    }

    /// First record matching a unique `constraint` and `value`,
    /// across all open documents, or `nil`. First-match-wins in
    /// document connect order (uniqueness is per-document, so the
    /// same value may exist in more than one open doc). Mirrors the
    /// JS client's `Model.findByUnique(constraintName, value)`.
    static func findByUnique(_ constraint: String, _ value: PrimitiveValue) throws -> ReservedFieldProbe? {
        let row = try JsBaoClient.requireDefault()
            .codegen.findByUnique(primitiveSchema, constraint: constraint, value: value)
        return PrimitiveRowDecoder.decodeOne(row, as: ReservedFieldProbe.self)
    }

    /// The first record matching `filter` across all open documents,
    /// or `nil`. Equivalent to `query(filter, options).first` — mirrors
    /// the JS client's `Model.queryOne(filter, options)`.
    static func queryOne(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil) throws -> ReservedFieldProbe? {
        let row = try JsBaoClient.requireDefault()
            .codegen.queryOne(primitiveSchema, filter: filter, options: options)
        return PrimitiveRowDecoder.decodeOne(row, as: ReservedFieldProbe.self)
    }

    /// The first record matching `filter` with query-time relationship
    /// includes attached under `related`, or `nil`. Equivalent to
    /// `query(filter, options, include:).first` — mirrors the JS client's
    /// `Model.queryOne(filter, { include })`.
    static func queryOne(_ filter: DocumentFilter? = nil, options: QueryOptions? = nil, include: [Include]) throws -> ReservedFieldProbe? {
        let row = try JsBaoClient.requireDefault()
            .codegen.queryOne(primitiveSchema, filter: filter, options: options, include: include)
        return PrimitiveRowDecoder.decodeOne(row, as: ReservedFieldProbe.self)
    }

    /// Fire `callback` after any add/update/delete in any open document's
    /// copy of this model (local or remote). Returns an unsubscribe closure.
    ///
    /// The callback is `@Sendable` (#1992): it runs on whichever thread
    /// committed the change — a local writer's thread, or the
    /// observer-drain queue — so state it captures must be safe to touch
    /// from either.
    @discardableResult
    static func subscribe(_ callback: @escaping @Sendable () -> Void) -> @Sendable () -> Void {
        JsBaoClient.requireDefault().codegen.subscribe(primitiveSchema, callback)
    }

    /// Aggregate (group / count / sum / avg / …) across all open documents.
    static func aggregate(_ options: AggregateOptions) throws -> [[String: JSONValue]] {
        try JsBaoClient.requireDefault().codegen.aggregate(primitiveSchema, options: options)
    }

    // MARK: Writes (target one document; throw if it isn't open)

    /// Persist this record to document `documentId` — inserts it if it
    /// doesn't exist yet, updates it in place if it does. One call for
    /// both, matching the JS client's `save()`. Throws if the doc isn't
    /// open.
    ///
    /// Updating writes only the fields assigned since this value was
    /// read (`_changedFields`), so two devices editing different fields
    /// of the same record merge instead of clobbering. Inserting writes
    /// every field.
    ///
    /// Returns the record AS SAVED, re-read from the document with no
    /// pending changes left — so a field this save didn't write carries
    /// whatever another device put there, and an insert's schema
    /// defaults and `auto_stamp` values are filled in. Assign it back
    /// (`task = try task.save(in: doc)`) when you keep using the value
    /// after the save; `self` itself still holds the values you had.
    @discardableResult
    func save(in documentId: String) throws -> ReservedFieldProbe {
        let record = try JsBaoClient.requireDefault().codegen.save(Self.primitiveSchema, id: id, values: primitiveValues(), in: documentId, changedFields: _changedFields)
        guard var saved = ReservedFieldProbe(record: record) else {
            var fallback = self
            fallback.discardChanges()
            return fallback
        }
        // Carried over, not persisted: query-time includes and the
        // caller-pinned-id flag have no representation in the stored
        // record, and this path never changes the record's id.
        saved.related = related
        saved._explicitId = _explicitId
        return saved
    }

    /// Insert-or-update this record in `documentId`, matched by the
    /// single-field unique constraint on `upsertOn` rather than `id` —
    /// if a record already holds this row's `upsertOn` value, that
    /// record is merged into (and keeps its id); otherwise a new
    /// record is inserted. Mirrors the JS client's
    /// `save({ upsertOn: field })`. Throws if the doc isn't open, if
    /// `upsertOn` has no single-field unique constraint, or if the
    /// `upsertOn` value is absent/empty.
    ///
    /// Returns the RESOLVED record: on the merge path its `id` is the
    /// EXISTING record's id (JS reassigns `this.id = existingId`) and
    /// its fields reflect the merged state, NOT necessarily `self`.
    @discardableResult
    func save(in documentId: String, upsertOn: String) throws -> ReservedFieldProbe {
        let result = try JsBaoClient.requireDefault().codegen.upsert(Self.primitiveSchema, id: id, values: primitiveValues(), on: upsertOn, in: documentId, explicitId: _explicitId, changedFields: _changedFields)
        if let resolved = ReservedFieldProbe(record: result.record) { return resolved }
        var copy = self
        copy.id = result.record.id
        copy.discardChanges()
        return copy
    }

    /// Insert-or-update this record, matched by the NAMED unique
    /// constraint (single-field or compound). Mirrors the JS client's
    /// `Model.upsertByUnique(constraintName, lookupValue, data,
    /// options)` — the lookup values come straight from this record's
    /// fields (every constraint field must be set), and `mode` maps
    /// JS's flags: `.mustExist` ⇔ `objectMustExist`, `.mustNotExist`
    /// ⇔ `objectMustNotExist`, `.either` ⇔ default.
    ///
    /// Search scope matches js-bao: the existing-record lookup spans
    /// EVERY open document. A match in any open doc is then saved
    /// through the explicit `documentId` target, matching JS
    /// `existingRecord.save({ targetDocument })`; a fresh insert also
    /// lands in `documentId`. Throws if the
    /// constraint isn't declared, a constraint field is unset, an
    /// explicit (pinned) id collides with a matched record
    /// (`UpsertError.explicitIdConflict`), or (on insert) `documentId`
    /// isn't open.
    ///
    /// Returns the RESOLVED record: on the merge path its `id` is the
    /// EXISTING record's id and its fields reflect the merged state.
    @discardableResult
    func upsertByUnique(_ constraint: String, mode: UpsertMode = .either, in documentId: String) throws -> ReservedFieldProbe {
        let result = try JsBaoClient.requireDefault().codegen.upsertByUnique(Self.primitiveSchema, id: id, values: primitiveValues(), constraint: constraint, mode: mode, in: documentId, explicitId: _explicitId, changedFields: _changedFields)
        if let resolved = ReservedFieldProbe(record: result.record) { return resolved }
        var copy = self
        copy.id = result.record.id
        copy.discardChanges()
        return copy
    }

    /// `upsertByUnique` overload taking an EXPLICIT lookup value (one
    /// per constraint field) — mirrors js-bao's separate
    /// `uniqueLookupValue` argument. The values must agree with this
    /// record's own constraint fields (js-bao throws on mismatch). Use
    /// when you want to make the lookup key explicit at the call site.
    @discardableResult
    func upsertByUnique(_ constraint: String, lookupValue: [PrimitiveValue], mode: UpsertMode = .either, in documentId: String) throws -> ReservedFieldProbe {
        let result = try JsBaoClient.requireDefault().codegen.upsertByUnique(Self.primitiveSchema, id: id, values: primitiveValues(), constraint: constraint, mode: mode, in: documentId, explicitId: _explicitId, uniqueLookupValue: lookupValue, changedFields: _changedFields)
        if let resolved = ReservedFieldProbe(record: result.record) { return resolved }
        var copy = self
        copy.id = result.record.id
        copy.discardChanges()
        return copy
    }

    /// Delete this record from document `documentId`. Throws if the doc isn't open.
    func delete(in documentId: String) throws {
        try JsBaoClient.requireDefault().codegen.delete(Self.primitiveSchema, id: id, in: documentId)
    }

    /// `save(in:)` with a db3 write's guards. On a db3 the room judges
    /// them: `options.condition` (the record must match it, in the
    /// query filter grammar) and `options.ifNotExists` (the save lands
    /// only as a create, while no live record has this id). A guarded
    /// save shows on this device only once the room accepts it. With
    /// `options.confirm` the call returns once the room accepted the
    /// save and throws its refusal: `.db3ConditionNotMet`, with the
    /// record as it is now under `details["current"]`. While the db3
    /// is not subscribed, a confirmed save waits for the next subscribe.
    ///
    /// Returns the record as this device then shows it, with no pending
    /// changes left: with `confirm`, as saved; without it, a guarded
    /// save's values are not shown yet. On a document that is not a db3
    /// the options are ignored and it saves as `save(in:)` does.
    @discardableResult
    func save(in documentId: String, options: JsBaoClient.Db3WriteOptions) async throws -> ReservedFieldProbe {
        let record = try await JsBaoClient.requireDefault().codegen.save(Self.primitiveSchema, id: id, values: primitiveValues(), in: documentId, changedFields: _changedFields, options: options)
        guard var saved = ReservedFieldProbe(record: record) else {
            var fallback = self
            fallback.discardChanges()
            return fallback
        }
        // Carried over, not persisted: query-time includes and the
        // caller-pinned-id flag have no representation in the stored
        // record, and this path never changes the record's id.
        saved.related = related
        saved._explicitId = _explicitId
        return saved
    }

    /// Delete this record from db3 `documentId` only if it matches
    /// `options.condition`, which the room judges. With
    /// `options.confirm` the call returns once the room accepted the
    /// delete and throws its refusal (`.db3ConditionNotMet`); while the
    /// db3 is not subscribed, it waits for the next subscribe. With
    /// neither, and on a document that is not a db3, it deletes as
    /// `delete(in:)` does.
    func delete(in documentId: String, options: JsBaoClient.Db3WriteOptions) async throws {
        try await JsBaoClient.requireDefault().codegen.delete(Self.primitiveSchema, id: id, in: documentId, options: options)
    }

    /// Add each of `fields` to record `id`'s number fields in db3
    /// `documentId`: a negative delta subtracts, and a missing field
    /// starts at 0. Increments made offline or on several devices at
    /// once all count. Answers each field's new value as this device
    /// shows it; with `options.confirm` or an `options.condition`, the
    /// room's values once it applied the increment, throwing its
    /// refusal (`.db3ConditionNotMet`, or `.db3RecordNotFound` for a
    /// record deleted meanwhile). A record this device does not hold
    /// throws `.db3RecordNotFound` and nothing is sent; a document that
    /// is not a db3 throws `.invalidArgument`. Mirrors the JS client's
    /// `Model.increment(id, fields, options)`.
    @discardableResult
    static func increment(id: String, fields: [String: Double], in documentId: String, options: JsBaoClient.Db3WriteOptions = JsBaoClient.Db3WriteOptions()) async throws -> [String: Double] {
        try await JsBaoClient.requireDefault().codegen.increment(primitiveSchema, id: id, fields: fields, in: documentId, options: options)
    }
}
